BEGIN;

DELETE FROM questions WHERE topic = 'Reproduction' AND subtopic IN ('Cell Cycle Control & Checkpoints', 'Cell Cycle Phases & Interphase', 'Loss of Cell-Cycle Control & Cancer', 'Mitosis Phases', 'Mitotic Structures');

-- Q1 [Cell Cycle Phases & Interphase | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub1$Cell Cycle Phases & Interphase$sub1$, $qt1$A cytologist labels a cultured animal cell at the exact moment it enters the synthesis (S) phase of interphase and follows it until the moment it exits S phase. The defining molecular event that occurs in the cell during this window is that:$qt1$, $op1$[{"label": "A", "text": "DNA is replicated, generating pairs of identical sister chromatids that are firmly attached to each other at the centromeric region."}, {"label": "B", "text": "DNA building blocks and energy reserves are accumulated to prepare the cell for the upcoming replication of each chromosome."}, {"label": "C", "text": "Proteins required for chromosome movement are synthesized while the cytoskeleton is dismantled to supply resources for division."}, {"label": "D", "text": "The duplicated chromosomes are condensed, aligned, and segregated as they are pulled toward opposite poles of the cell."}]$op1$::jsonb, 'A', $ex1$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is A because the hallmark event that defines S (synthesis) phase is DNA replication, which produces identical paired DNA molecules called sister chromatids joined at the centromere. The text states that "In the S phase, DNA replication can proceed through the mechanisms that result in the formation of identical pairs of DNA molecules—sister chromatids—that are firmly attached at the centromeric region," and adds that "The centrosome is also duplicated during the S phase." The other listed events belong to different stages of the cell cycle: the gap phases (G1 and G2) prepare for and follow replication, and chromosome segregation occurs in the mitotic phase, not interphase. Recognizing which molecular event names S phase therefore depends on assigning DNA replication specifically to this stage. (Choice A) is correct because replicating DNA into centromere-linked sister chromatids is the textbook-defining event of S phase. (Choice B) describes the G1 phase, during which the cell is "accumulating the building blocks of chromosomal DNA... as well as accumulating sufficient energy reserves to complete the task of replicating each chromosome," not S phase itself. (Choice C) describes the G2 phase, in which the cell "synthesizes proteins necessary for chromosome manipulation and movement" and "the cytoskeleton is dismantled to provide resources for the mitotic phase." (Choice D) describes the mitotic phase, during which "the replicated DNA and cytoplasmic contents are separated" and "the duplicated chromosomes are segregated," which follows interphase rather than occurring within S phase. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling and correctly assigning the defining biochemical event (DNA replication into sister chromatids) to the S phase of the cell cycle.$ex1$, 'easy', '2C', $cc1$Cell Cycle & Mitosis (BIO)$cc1$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'process_step_confusion', $a1B$Attributing the G1 preparatory role (accumulating DNA building blocks and energy reserves) to S phase$a1B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a1C$Attributing the G2 role (synthesizing movement proteins and dismantling the cytoskeleton) to S phase$a1C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a1D$Attributing the mitotic-phase role (chromosome condensation, alignment, and segregation) to S phase$a1D$ FROM q;

-- Q2 [Cell Cycle Phases & Interphase | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub2$Cell Cycle Phases & Interphase$sub2$, $qt2$A mature cardiac muscle cell in an adult heart has permanently stopped dividing; it carries out its contractile functions but has exited the cell cycle entirely and is not preparing to replicate its DNA or undergo mitosis. In which stage is this non-dividing cell resting?$qt2$, $op2$[{"label": "A", "text": "It is in G1, the first gap phase of interphase, during which the cell actively grows and accumulates the materials needed to replicate its chromosomes."}, {"label": "B", "text": "It is in G0, a quiescent stage entered when a cell exits the cell cycle and is not actively preparing to divide."}, {"label": "C", "text": "It is in G2, the second gap phase of interphase, during which the cell makes its final preparations before entering the mitotic phase."}, {"label": "D", "text": "It is in S phase, the synthesis stage of interphase, during which the cell replicates its nuclear DNA to form sister chromatids."}]$op2$::jsonb, 'B', $ex2$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is B because the cell has exited the cell cycle and is not preparing to divide, which is the defining feature of the quiescent G0 phase. The text states that "Cells in G0 phase are not actively preparing to divide. The cell is in a quiescent (inactive) stage that occurs when cells exit the cell cycle," and it specifically notes that "cells that never or rarely divide, such as mature cardiac muscle and nerve cells, remain in G0 permanently." The three gap and synthesis stages named in the other choices (G1, S, and G2) are all stages of interphase in which a cell is actively progressing toward division, so none of them describes a cell that has left the cycle altogether. (Choice A) G1 is the first gap phase in which the cell is actively growing and accumulating DNA building blocks in preparation for division, not a stage in which the cell has exited the cycle. (Choice B) G0 is correct because it is the quiescent, non-dividing state entered when a cell exits the cell cycle, illustrated by permanently non-dividing cardiac muscle and nerve cells. (Choice C) G2 is the second gap phase in which the cell makes final preparations for mitosis, so a cell in G2 is committed to dividing rather than resting outside the cycle. (Choice D) S phase is the synthesis stage in which DNA replication produces sister chromatids, an active step of cycle progression rather than a quiescent exit. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the definition of the G0 phase as a quiescent state outside the cell cycle and recognizing cardiac muscle as a textbook example of permanently non-dividing cells.$ex2$, 'easy', '2C', $cc2$Cell Cycle & Mitosis (BIO)$cc2$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a2A$Naming a real interphase gap stage (G1) of active growth instead of the quiescent out-of-cycle G0 state$a2A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a2C$Naming a real interphase gap stage (G2) of pre-mitotic preparation instead of the quiescent out-of-cycle G0 state$a2C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a2D$Naming a real interphase synthesis stage (S) of DNA replication instead of the quiescent out-of-cycle G0 state$a2D$ FROM q;

-- Q3 [Cell Cycle Phases & Interphase | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub3$Cell Cycle Phases & Interphase$sub3$, $qt3$A cell biologist studies a line of cultured cells and identifies the single point in the cycle past which a cell can no longer reverse its decision to divide: once a cell clears this point it is committed to proceed, and a cell that fails it is blocked from entering the DNA-synthesis stage altogether. Which checkpoint has the biologist most likely characterized?$qt3$, $op3$[{"label": "A", "text": "The G2 checkpoint, because it confirms that the chromosomes have been completely replicated before the cell enters mitosis"}, {"label": "B", "text": "The M (spindle) checkpoint, because it verifies that each kinetochore is attached to spindle fibers before the cell proceeds to anaphase"}, {"label": "C", "text": "The G1 checkpoint, because it is the point at which the cell irreversibly commits to division and blocks a failing cell from entering S phase"}, {"label": "D", "text": "The S-phase checkpoint, because it monitors DNA replication as it proceeds and commits the cell to division during synthesis"}]$op3$::jsonb, 'C', $ex3$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is C because the G1 checkpoint, also called the restriction point, is the point at which the cell irreversibly commits to the cell division process, and a cell that fails it is not allowed to progress into S phase. The text states the G1 checkpoint "is a point at which the cell irreversibly commits to the cell division process" and that "A cell that does not meet all the requirements will not be allowed to progress into the S phase." Two features in the scenario pin down this gate: the irreversible commitment to divide and the block on entering the DNA-synthesis (S) stage. The other named checkpoints (G2 and M) follow S phase and govern different transitions, so they cannot be the gate into S phase. (Choice A) The G2 checkpoint's "most important role" is "to ensure that all of the chromosomes have been replicated," but it acts after S phase to bar entry into mitosis, not before it, so it is not the commitment gate into S phase. (Choice B) The M (spindle) checkpoint guards an irreversible step—"the separation of the sister chromatids during anaphase"—but that is a different irreversible event than the commitment to divide, and it occurs near the end of metaphase, long after S phase. (Choice C) is correct because the G1 checkpoint is described as the point of irreversible commitment to division and the gate that a failing cell cannot pass to reach S phase. (Choice D) The text describes DNA replication proceeding during S phase but lists only three main checkpoints—near the end of G1, at the G2/M transition, and during metaphase—so treating ongoing synthesis itself as the commitment gate misidentifies the controlling checkpoint. This is a Scientific Reasoning and Problem Solving question because it requires interpreting the described functional criteria of a checkpoint—irreversible commitment plus the block on entering S phase—and mapping those clues onto the correct named checkpoint while ruling out checkpoints that govern later transitions.$ex3$, 'medium', '2C', $cc3$Cell Cycle & Mitosis (BIO)$cc3$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a3A$Real downstream checkpoint (G2) whose true function is correctly stated but placed after S phase, so it cannot be the gate into S phase or the commitment point$a3A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a3B$Real checkpoint guarding a different irreversible step (anaphase onset) is swapped for the irreversible commitment to divide$a3B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a3D$Invents/mislabels S-phase replication monitoring as the commitment gate, treating synthesis itself as the decision point$a3D$ FROM q;

-- Q4 [Cell Cycle Phases & Interphase | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub4$Cell Cycle Phases & Interphase$sub4$, $qt4$A histologist fixes and stains a slice of rapidly dividing human tissue whose cells run a 24-hour cycle, then picks one cell at random from the field of view. Given that G1 lasts about 9 hours, S about 10 hours, G2 about 4.5 hours, and M about half an hour, the randomly chosen cell is MOST likely to be captured in which portion of the cycle?$qt4$, $op4$[{"label": "A", "text": "Metaphase, the point at which the duplicated chromosomes are maximally condensed and most clearly resolved under the microscope"}, {"label": "B", "text": "Prophase, the opening step of the mitotic phase during which the spindle assembles and chromosomes first become visible"}, {"label": "C", "text": "S phase alone, the single ~10-hour interval during which the nuclear DNA is replicated into sister chromatids"}, {"label": "D", "text": "Interphase, the combined G1, S, and G2 period that together occupies roughly 23.5 of the cycle's 24 hours"}]$op4$::jsonb, 'D', $ex4$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is D because in a population fixed at random moments, the fraction of cells caught in any phase is proportional to how long that phase lasts, and interphase (G1 + S + G2 = 9 + 10 + 4.5 = 23.5 hours) consumes nearly the entire 24-hour cycle while the M phase lasts only about half an hour. The text states that "the G1 phase lasts approximately nine hours, the S phase lasts 10 hours, the G2 phase lasts about four and one-half hours, and the M phase lasts approximately one-half hour," and it defines the three stages of interphase as G1, S, and G2. Because roughly 23.5 of every 24 hours are spent in interphase, a random snapshot will almost always land there. (Choice A) Metaphase is when chromosomes are "maximally condensed" and thus most visible, but visibility is not duration—mitosis as a whole occupies only about half an hour, so a random cell is rarely caught at metaphase. (Choice B) Prophase opens the brief ~0.5-hour M phase; treating mitosis as the time-dominant part of the cycle overestimates how long cells spend there. (Choice C) S phase is the single longest individual step at 10 hours, but it is only one stage of interphase; all of interphase (23.5 hours) is far more probable than S phase alone. (Choice D) Interphase spans G1, S, and G2, totaling 23.5 of 24 hours, so it is overwhelmingly the most likely phase to catch at random. This is a Scientific Reasoning and Problem Solving question because it requires converting per-phase durations into relative probabilities and inferring which phase a random sample most likely represents.$ex4$, 'medium', '2C', $cc4$Cell Cycle & Mitosis (BIO)$cc4$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a4A$conflating chromosome visibility/condensation with time spent in the phase$a4A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a4B$overestimating the brief M phase by treating mitosis as the time-dominant active part of the cycle$a4B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a4C$mistaking the longest single interphase step (S, ~10 h) for the most probable overall state instead of all of interphase$a4C$ FROM q;

-- Q5 [Cell Cycle Phases & Interphase | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub5$Cell Cycle Phases & Interphase$sub5$, $qt5$A cell that began the cycle with 46 chromosomes completes S phase normally and is arrested in G2 just before entering mitosis. A student is asked to compare the cell's nuclear DNA content and its chromosome count in this G2 state with the values it had during G1. What is the most accurate prediction?$qt5$, $op5$[{"label": "A", "text": "The amount of nuclear DNA has doubled, but the chromosome number is still 46, because each chromosome is now two sister chromatids joined at a single centromere."}, {"label": "B", "text": "Both the amount of nuclear DNA and the chromosome number have doubled, because replication produces twice as many separate chromosomes from the original set."}, {"label": "C", "text": "The amount of nuclear DNA is unchanged, but the chromosome number has doubled to 92, because S phase adds new chromosomes to the nucleus."}, {"label": "D", "text": "The amount of nuclear DNA has doubled, and the chromosome number has already doubled to 92, because cohesin degrades and the chromatids separate at the centromere."}]$op5$::jsonb, 'A', $ex5$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is A because S phase doubles the nuclear DNA, yet each replicated chromosome remains a single chromosome consisting of two sister chromatids held together at one centromere, so the chromosome number does not change in G2. The text states that "In the S phase, DNA replication can proceed through the mechanisms that result in the formation of identical pairs of DNA molecules—sister chromatids—that are firmly attached at the centromeric region," and that "After replication, the chromosomes are composed of two linked sister chromatids... The connection between the sister chromatids is closest in a region called the centromere." Because the two chromatids stay joined at one centromere, the structure is still counted as one chromosome; the count of 46 is therefore unchanged in G2 while the DNA quantity has doubled. Only at anaphase does this change, when "the cohesin proteins degrade, and the sister chromatids separate at the centromere. Each chromatid, now called a single chromosome," doubling the count after G2. (Choice A) is correct: doubled DNA with an unchanged chromosome number of 46 reflects 46 two-chromatid chromosomes still joined at single centromeres. (Choice B) is wrong because replication does not create separate chromosomes; it makes sister chromatids that share one centromere, so the number stays 46 even though DNA doubles. (Choice C) reverses the relationship, claiming DNA is constant while chromosome number doubles, but S phase is precisely the synthesis of DNA, and the chromatids remain joined as one chromosome. (Choice D) describes the anaphase outcome, where cohesin degrades and separated chromatids each become a chromosome (count 92); that event has not occurred in the G2 state being asked about. This is a Scientific Reasoning and Problem Solving question because it requires chaining the molecular event of S-phase replication to the centromere-joined sister-chromatid architecture in order to predict, for a specific G2 cell, how DNA amount and chromosome number diverge.$ex5$, 'hard', '2C', $cc5$Cell Cycle & Mitosis (BIO)$cc5$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a5B$Treating S-phase replication as if it produces twice as many separate chromosomes rather than paired chromatids sharing one centromere$a5B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a5C$Swapping which quantity S phase changes—holding DNA constant while doubling chromosome number$a5C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a5D$Applying the anaphase result (cohesin degrades, chromatids separate, count doubles) to the G2 state where it has not yet happened$a5D$ FROM q;

-- Q6 [Cell Cycle Control & Checkpoints | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub6$Cell Cycle Control & Checkpoints$sub6$, $qt6$A cultured cell has completed metaphase, with its duplicated chromosomes aligned at the metaphase plate, and is poised to enter the irreversible separation of sister chromatids. Before the cell is permitted to advance, the spindle (M) checkpoint confirms one specific condition. What does this checkpoint verify?$qt6$, $op6$[{"label": "A", "text": "Whether all of the chromosomes have been completely and correctly replicated"}, {"label": "B", "text": "Whether the kinetochores of each pair of sister chromatids are firmly anchored to spindle fibers arising from opposite poles of the cell"}, {"label": "C", "text": "Whether the cell has reached adequate size and accumulated sufficient protein reserves and growth-factor signaling to commit to division"}, {"label": "D", "text": "Whether the genomic DNA is free of damage so that mutations are not passed to daughter cells"}]$op6$::jsonb, 'B', $ex6$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is B because the M (spindle) checkpoint, occurring near the end of metaphase, verifies that the kinetochores of every pair of sister chromatids are firmly anchored to spindle fibers from opposite poles before anaphase begins. The text states that because the separation of sister chromatids during anaphase is an irreversible step, "the cycle will not proceed until the kinetochores of each pair of sister chromatids are firmly anchored to at least two spindle fibers arising from opposite poles of the cell." This bipolar attachment ensures each daughter cell receives a complete, correct chromosome set. The other criteria listed belong to earlier checkpoints (G1 and G2), not the M checkpoint. (Choice A) is incorrect because confirming that all chromosomes have been correctly replicated is the role of the G2 checkpoint, which acts at the G2/M transition before mitosis. (Choice B) is correct because the M checkpoint specifically determines whether the sister chromatids are correctly attached to spindle microtubules from opposing poles. (Choice C) is incorrect because assessing adequate cell size, reserves, and growth-factor signaling is the function of the G1 checkpoint (the restriction point), where the cell commits to division. (Choice D) is incorrect because checking that genomic DNA is undamaged is performed at the G1 checkpoint (and again at G2), not at the M checkpoint. This is a Knowledge of Scientific Concepts and Principles question because it requires the student to recall the defined function of a specific cell-cycle checkpoint as described in the textbook.$ex6$, 'easy', '2C', $cc6$Cell Cycle & Mitosis (BIO)$cc6$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a6A$Attributes the G2 checkpoint's replication-completion check to the M checkpoint$a6A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a6C$Attributes the G1 restriction-point criteria (size, reserves, growth factors) to the M checkpoint$a6C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a6D$Attributes the G1/G2 DNA-integrity check to the M checkpoint$a6D$ FROM q;

-- Q7 [Cell Cycle Control & Checkpoints | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub7$Cell Cycle Control & Checkpoints$sub7$, $qt7$An investigator engineers cells in which the concentration of a Cdk protein is held constant at a high level while the concentration of its partner cyclin is experimentally clamped at a very low level throughout interphase. The investigator then asks whether these cells can transition past a cell-cycle checkpoint. What outcome should the investigator predict?$qt7$, $op7$[{"label": "A", "text": "The cell advances normally, because the abundant, stable Cdk phosphorylates its target proteins on its own and drives the cell past the checkpoint."}, {"label": "B", "text": "The cell advances faster, because the low cyclin level removes the brake that cyclin normally places on Cdk activity at the checkpoint."}, {"label": "C", "text": "The cell fails to advance past the checkpoint, because Cdks regulate the cycle only when bound to cyclin, and the fluctuating cyclin concentration determines when the activating complexes form."}, {"label": "D", "text": "The cell arrests only at the M checkpoint, because cyclin is required exclusively for attaching chromatids to the spindle and not for earlier transitions."}]$op7$::jsonb, 'C', $ex7$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is C because Cdks are catalytically meaningful for cell-cycle progression only as part of a Cdk/cyclin complex, and the text states that the relatively stable Cdk levels are not limiting; rather, the fluctuating cyclin concentration determines when the activating complexes can form. With cyclin clamped low, a sufficient concentration of fully activated cyclin/Cdk complexes cannot accumulate, so the cell cannot proceed through the checkpoint regardless of how much Cdk is present. The text is explicit that "Cyclins regulate the cell cycle only when they are tightly bound to Cdks" and that "Without a specific concentration of fully activated cyclin/Cdk complexes, the cell cycle cannot proceed through the checkpoints." (Choice A) is wrong because a free Cdk is not independently active; full activity requires binding cyclin and then phosphorylation, so abundant Cdk alone cannot phosphorylate targets to advance the cycle. (Choice B) reverses the relationship, since cyclin is the required positive activator of Cdk, not a brake, so lowering cyclin removes activation rather than removing inhibition. (Choice C) is correct because cyclin is the limiting, fluctuating partner whose binding (followed by phosphorylation) creates the active complexes needed to clear the checkpoint, and clamping it low blocks progression. (Choice D) is a partial truth that wrongly confines cyclin's role to the M (spindle) checkpoint; different cyclins and Cdks act at multiple checkpoints, so low cyclin would impair earlier G1/G2 transitions as well, not just M. This is a Scientific Reasoning and Problem Solving question because the student must take the experimental manipulation of two molecular variables and predict the downstream effect on checkpoint progression by reasoning from the cyclin/Cdk activation mechanism rather than recalling a single fact.$ex7$, 'medium', '2C', $cc7$Cell Cycle & Mitosis (BIO)$cc7$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a7A$Cdk is independently catalytically active without a cyclin partner$a7A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a7B$Treating cyclin as a negative inhibitor (brake) rather than the required positive activator of Cdk$a7B$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a7D$Confining cyclin's role to a single (M/spindle) checkpoint instead of multiple transitions$a7D$ FROM q;

-- Q8 [Cell Cycle Control & Checkpoints | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub8$Cell Cycle Control & Checkpoints$sub8$, $qt8$A cell in G1 is hit with ionizing radiation that introduces double-strand breaks into its genomic DNA before it has entered S phase. A researcher tracks the cell and finds that it arrests, attempts to mend the lesions, and then self-destructs when the breaks prove unrepairable. Which negative regulator most directly orchestrates this arrest-repair-or-die response?$qt8$, $op8$[{"label": "A", "text": "Rb, which in its dephosphorylated state binds E2F to gauge cell size and blocks the G1/S transition until the cell has grown large enough"}, {"label": "B", "text": "The cell advances into S phase and the lesions are instead caught at the G2 checkpoint, which verifies that the replicated DNA is undamaged"}, {"label": "C", "text": "p21, which directly senses the double-strand breaks and signals apoptosis while acting upstream of p53 in the damage response"}, {"label": "D", "text": "p53, which halts the cycle and recruits DNA-repair enzymes, then triggers apoptosis if the breaks cannot be repaired so the damaged chromosomes are not duplicated"}]$op8$::jsonb, 'D', $ex8$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is D because p53 is the multifunctional negative regulator that acts on DNA damage detected during G1, halting the cycle, recruiting repair enzymes, and triggering apoptosis when repair is impossible. The text states that "p53 is a multi-functional protein that has a major impact on the commitment of a cell to division because it acts when there is damaged DNA in cells that are undergoing the preparatory processes during G1," and that "If damaged DNA is detected, p53 halts the cell cycle and then recruits specific enzymes to repair the DNA. If the DNA cannot be repaired, p53 can trigger apoptosis, or cell suicide, to prevent the duplication of damaged chromosomes." This three-part role (arrest, repair, apoptosis) is exactly the scenario described, and it operates at the G1 checkpoint where "there is a check for genomic DNA damage," not at the spindle (M) check or the replication-verifying G2 check. (Choice A) Rb is a real G1 negative regulator, but the text says it "largely monitors cell size" and "binds to proteins called transcription factors, most commonly, E2F" to block the G1/S transition as the cell grows, which is the size-gating function, not the DNA-damage response. (Choice B) The G2 checkpoint does "ensure that all of the chromosomes have been replicated and that the replicated DNA is not damaged," but the damage here is detected in G1 before replication, and the text states a cell that fails the G1 DNA-damage check "will not be allowed to progress into the S phase," so the lesions are not deferred to G2. (Choice C) p21 is involved, but the text reverses its order: "As p53 levels rise, the production of p21 is triggered. p21 enforces the halt in the cycle dictated by p53 by binding to and inhibiting the activity of the Cdk/cyclin complexes," making p21 a downstream enforcer, not the upstream sensor that initiates apoptosis. (Choice D) p53 correctly halts the cycle, recruits repair enzymes, and triggers apoptosis if the DNA cannot be repaired, matching the passage precisely. This is a Scientific Reasoning and Problem Solving question because it requires interpreting a damage scenario, predicting the regulator's sequential actions, and distinguishing the G1 DNA-integrity response from the size-monitoring, replication-verifying, and spindle-attachment checks.$ex8$, 'medium', '2C', $cc8$Cell Cycle & Mitosis (BIO)$cc8$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a8A$Substitutes Rb's genuine but distinct size-monitoring/E2F mechanism for the DNA-damage response$a8A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a8B$Shifts the G1 DNA-damage check to the later G2 replication-verification checkpoint$a8B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a8C$Reverses the p53-to-p21 hierarchy, casting the downstream enforcer p21 as the upstream initiator$a8C$ FROM q;

-- Q9 [Cell Cycle Control & Checkpoints | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub9$Cell Cycle Control & Checkpoints$sub9$, $qt9$A tumor cell carries a p53 mutation that abolishes p53's ability to induce production of p21, although the cell's Cdk, cyclin, and Rb proteins are themselves normal. A researcher introduces unrepaired double-strand DNA breaks into this cell while it is in G1 and then tracks whether the cell halts or advances. What is the MOST likely outcome for this cell at the G1 checkpoint?$qt9$, $op9$[{"label": "A", "text": "It advances from G1 into S phase despite the DNA damage, because without p21 there is no effective block on Cdk/cyclin activation and the G1 checkpoint is compromised."}, {"label": "B", "text": "It arrests permanently in G1 despite lacking p21, because p53 itself binds to and inhibits the Cdk/cyclin complexes that drive the G1/S transition."}, {"label": "C", "text": "It completes G1 normally but then arrests at the G2 checkpoint, where the unrepaired DNA damage is detected and the Cdk/cyclin complex is blocked."}, {"label": "D", "text": "It still arrests in G1 because Rb remains bound to E2F and blocks the G1/S transition independently of the p53-p21 pathway."}]$op9$::jsonb, 'A', $ex9$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is A because p53 enforces the G1 DNA-damage halt only indirectly: rising p53 triggers p21 production, and it is p21 that physically binds and inhibits the Cdk/cyclin complexes, so a p53 that cannot induce p21 leaves Cdk/cyclin unblocked. The text states that "p21 enforces the halt in the cycle dictated by p53 by binding to and inhibiting the activity of the Cdk/cyclin complexes," and that when "Mutated p53 might lose its ability to trigger p21 production. Without adequate levels of p21, there is no effective block on Cdk activation." It concludes that "without a fully functional p53, the G1 checkpoint is severely compromised and the cell proceeds directly from G1 to S regardless of internal and external conditions," which is exactly the predicted advance despite DNA damage. (Choice A) Correct: with no p21, the Cdk/cyclin block is missing, the G1 checkpoint fails, and the cell moves into S phase regardless of conditions. (Choice B) Incorrect: p53 does not itself bind and inhibit Cdk/cyclin; the text assigns that inhibitory binding to p21, the molecule this cell can no longer produce, so there is no direct p53-driven arrest. (Choice C) Incorrect: relocating the failed control to G2 misreads the pathway, because Rb, p53, and p21 "act primarily at the G1 checkpoint," and the G2 checkpoint instead chiefly verifies that "all of the chromosomes have been replicated"; the lost p53-p21 brake does not reappear there. (Choice D) Incorrect: Rb is a genuine G1 negative regulator, but it "largely monitors cell size" and releases E2F as the cell grows; it cannot substitute for the p53-driven DNA-damage halt, so a growing cell with intact Rb will still phosphorylate Rb and release E2F. This is a Scientific Reasoning and Problem Solving question because it requires chaining the p53 to p21 to Cdk-inhibition mechanism to predict the cell's behavior in a novel mutant scenario rather than recalling a single fact.$ex9$, 'hard', '2C', $cc9$Cell Cycle & Mitosis (BIO)$cc9$, 'biology', 2, 160
  ) RETURNING id
)
