UNION ALL SELECT id, 'C', 'misconception', $a10C$inverting Cdk activation logic by claiming cyclin dephosphorylates the Cdk, so an activating mutation is wrongly judged to have no effect$a10C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a10D$correct that p53 acts at G1 and can trigger apoptosis, but wrong that it surveils an individual Cdk's activation state rather than DNA damage/cell stress$a10D$ FROM q;

-- Q11 [Loss of Cell-Cycle Control & Cancer | easy | Skill 1 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub11$Loss of Cell-Cycle Control & Cancer$sub11$, $qt11$A previously normal positive cell-cycle regulator gene in a colon cell acquires a mutation, and the altered protein it now encodes pushes the cell through its checkpoints faster than normal, driving the cell to divide uncontrollably. The mutated gene in this cell is now classified as:$qt11$, $op11$[{"label": "A", "text": "a tumor suppressor gene, whose protein normally halts the cell cycle so that its loss removes a brake on division"}, {"label": "B", "text": "a proto-oncogene, the normal positive-regulator gene that is harmless until it is altered by mutation"}, {"label": "C", "text": "an oncogene, a mutated gene whose altered protein increases the rate of cell-cycle progression"}, {"label": "D", "text": "a mutated negative-regulator gene whose protein can no longer signal the enzymes that repair damaged DNA"}]$op11$::jsonb, 'C', $ex11$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is C because an oncogene is precisely a gene that, once altered, leads to an increase in the rate of cell-cycle progression, which matches the scenario of an altered protein pushing the cell through checkpoints faster and driving uncontrolled division. The text defines proto-oncogenes as the genes coding for positive cell-cycle regulators and states they "become oncogenes—genes that cause a cell to become cancerous" when mutated, and explicitly that "An oncogene is any gene that, when altered, leads to an increase in the rate of cell-cycle progression." Because the gene described started as a positive regulator and its mutation accelerates the cycle, its mutated form is by definition an oncogene rather than its un-mutated precursor or a negative regulator. (Choice A) is incorrect because a tumor suppressor gene codes for negative regulators that "prevent the cell from undergoing uncontrolled division"; it is the opposite gene class, and cancer arises from its loss, not its gain of activity. (Choice B) is incorrect because the proto-oncogene is the normal, un-mutated precursor that is harmless until altered, whereas the scenario describes the gene after it has already been mutated. (Choice C) is correct because the mutated positive regulator that speeds cell-cycle progression is exactly what defines an oncogene. (Choice D) is incorrect because a mutated negative regulator unable to signal DNA-repair enzymes describes a damaged tumor suppressor such as p53, not an oncogene. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling and applying the textbook definition of an oncogene as the mutated form of a proto-oncogene that increases cell-cycle progression.$ex11$, 'easy', '2C', $cc11$Cell Cycle & Mitosis (BIO)$cc11$, 'biology', 1, 75
  ) RETURNING id
)
