UNION ALL SELECT id, 'B', 'partial_truth', $a11B$Correct precursor gene but the un-mutated form, not the cancer-causing mutated form described in the scenario$a11B$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a11D$Conflates an oncogene with a damaged tumor-suppressor function (p53-type loss of DNA-damage signaling)$a11D$ FROM q;

-- Q12 [Loss of Cell-Cycle Control & Cancer | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub12$Loss of Cell-Cycle Control & Cancer$sub12$, $qt12$A cultured cell sustains DNA damage and reaches the end of G1, but a mutation has rendered its p53 protein completely non-functional. A researcher predicts what this cell will do next at the G1 checkpoint. Which outcome is MOST likely?$qt12$, $op12$[{"label": "A", "text": "It arrests permanently in G1 because, without p53, p21 is continuously produced and locks the Cdk/cyclin complexes off."}, {"label": "B", "text": "It instead halts at the G2/M transition, where a backup surveillance system blocks the cell from entering mitosis."}, {"label": "C", "text": "It still arrests in G1 but skips DNA repair and immediately triggers apoptosis to prevent the damage from spreading."}, {"label": "D", "text": "It proceeds directly from G1 into S phase and replicates its damaged DNA without arresting for repair."}]$op12$::jsonb, 'D', $ex12$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is D because, without a fully functional p53, the G1 checkpoint is severely compromised and the cell advances from G1 into S phase regardless of its internal damaged-DNA condition. Normally p53 acts at the G1 checkpoint: when it detects damaged DNA it halts the cycle and recruits repair enzymes, and rising p53 triggers p21 production, which enforces the halt by binding and inhibiting Cdk/cyclin complexes. When p53 is non-functional, it cannot drive p21 production, so there is no effective block on Cdk activation and the damage check fails; the text states the cell then "proceeds directly from G1 to S regardless of internal and external conditions," replicating the damaged DNA. The damaged version of p53 found in cancer cells also cannot trigger apoptosis, so the cell neither repairs, arrests, nor self-destructs. (Choice A) This reverses the regulatory logic: loss of p53 lowers p21, since "Mutated p53 might lose its ability to trigger p21 production," so Cdk/cyclin complexes are not locked off but instead left unrestrained. (Choice B) p53 and the genomic-DNA-damage arrest described act primarily at the G1 checkpoint, not the G2/M transition, so a G1 cell with non-functional p53 does not get rerouted to halt at G2/M. (Choice C) A cell with faulty p53 can neither reliably arrest nor trigger apoptosis, because "The damaged version of p53 found in cancer cells, however, cannot trigger apoptosis." (Choice D) This is correct because losing p53 removes the G1 damage block, allowing the cell to enter S phase and replicate uncorrected DNA. This is a Scientific Reasoning and Problem Solving question because it requires predicting a downstream cell-cycle outcome from a specified molecular lesion (non-functional p53) rather than recalling a single stated fact.$ex12$, 'medium', '2C', $cc12$Cell Cycle & Mitosis (BIO)$cc12$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a12A$Inverting the p53-to-p21 relationship so loss of p53 is claimed to raise p21 and cause permanent arrest$a12A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a12B$Relocating the p53-mediated DNA-damage arrest from the G1 checkpoint to the G2/M checkpoint$a12B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a12C$Granting a faulty-p53 cell a residual arrest-then-apoptosis function it does not retain$a12C$ FROM q;

-- Q13 [Loss of Cell-Cycle Control & Cancer | medium | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub13$Loss of Cell-Cycle Control & Cancer$sub13$, $qt13$A geneticist examines a colorectal tumor and finds that both copies of the gene encoding p53 carry frameshift mutations that abolish the protein's function, while the genes for Rb and p21 remain intact. The geneticist predicts that this loss-of-function change drives the tumor cells toward continuous division. The reasoning behind this prediction depends on correctly classifying what p53 normally does in the cell cycle. p53 promotes uncontrolled division when lost because it normally functions as:$qt13$, $op13$[{"label": "A", "text": "a tumor-suppressor protein that normally blocks cell-cycle progression, so losing its function removes a brake and permits uncontrolled division"}, {"label": "B", "text": "a proto-oncogene product that normally drives the cycle forward, so a mutation that hyperactivates it accelerates uncontrolled division"}, {"label": "C", "text": "a positive regulator like Cdk and cyclin, so losing its function stalls the cycle and prevents the cell from completing any further division"}, {"label": "D", "text": "a negative regulator at the G1 checkpoint, so losing its function leaves that checkpoint permanently engaged and arrests the cell cycle"}]$op13$::jsonb, 'A', $ex13$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is A because p53, like Rb and p21, is a negative regulator (tumor-suppressor protein) that normally halts the cycle, so a loss-of-function mutation removes that block and lets division proceed unchecked. The text states that the best-understood negative regulatory molecules are Rb, p53, and p21 and that their collective function is to put up a roadblock to cell-cycle progression until certain events are completed. It explicitly compares tumor suppressors to brakes in a vehicle and notes that a cell carrying a mutated negative regulator might not be able to halt the cell cycle if there is a problem, which is why loss of function (not gain) is the pathological direction. (Choice A) Correct: tumor suppressors act as brakes, so eliminating p53's function removes a block and permits the uncontrolled division the geneticist predicts. (Choice B) Incorrect: gain-of-function and proto-oncogene/oncogene logic describes positive regulators such as the Cdk gene, where a mutation increases activity; p53 is a negative regulator whose pathology is loss of function, not hyperactivation. (Choice C) Incorrect: Cdk and cyclin are the positive regulators that drive the cycle forward, and losing positive regulators would stall the cycle; p53 is the opposite type of molecule, so this misclassifies it. (Choice D) Incorrect: although p53 is correctly named a negative regulator at the G1 checkpoint, losing a brake releases the cycle rather than locking the checkpoint on, so its loss permits progression instead of arresting it. This is a Scientific Reasoning and Problem Solving question because the student must classify p53 as a negative regulator and then reason from that classification to predict the cell-cycle consequence of a loss-of-function mutation in the tumor scenario.$ex13$, 'medium', '2C', $cc13$Cell Cycle & Mitosis (BIO)$cc13$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a13B$Treats a tumor-suppressor (negative regulator) as a proto-oncogene product whose pathology is gain-of-function/hyperactivation$a13B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a13C$Misclassifies a negative regulator as a positive regulator (Cdk/cyclin), predicting loss would stall rather than release the cycle$a13C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a13D$Correctly labels it a negative regulator but reverses the effect of brake loss, claiming the checkpoint stays engaged and arrests the cycle$a13D$ FROM q;

-- Q14 [Loss of Cell-Cycle Control & Cancer | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub14$Loss of Cell-Cycle Control & Cancer$sub14$, $qt14$A dividing cell sustains DNA damage so severe that its repair enzymes cannot correct the lesions. In a healthy cell this cell would be eliminated, but this cell carries the faulty p53 protein typical of tumor cells, and it proceeds to divide. Which prediction BEST accounts for why losing functional p53 allows this irreparably damaged cell to pass its mutations to its daughters?$qt14$, $op14$[{"label": "A", "text": "Faulty p53 still triggers apoptosis, but it fires too readily and kills healthy cells before their DNA can even be checked for damage."}, {"label": "B", "text": "Functional p53 would deem the unrepairable cell unsalvageable and trigger apoptosis, whereas faulty p53 cannot trigger apoptosis, so the damaged cell survives and divides."}, {"label": "C", "text": "The cell depends on Rb to trigger apoptosis when DNA is unrepairable, so an intact Rb protein would still eliminate this damaged cell before it divides."}, {"label": "D", "text": "Functional p53 first repairs the DNA and then induces apoptosis as a routine final step, so daughter cells from a p53-competent parent are always damage-free."}]$op14$::jsonb, 'B', $ex14$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is B because functional p53 responds to irreparable DNA damage by deeming the cell unsalvageable and triggering apoptosis, a safeguard that prevents the duplication of damaged chromosomes, while the faulty p53 found in tumor cells cannot trigger apoptosis at all. The text states that "If the DNA cannot be repaired, p53 can trigger apoptosis, or cell suicide, to prevent the duplication of damaged chromosomes" and that "a functional p53 will deem the cell unsalvageable and trigger programmed cell death (apoptosis). The damaged version of p53 found in cancer cells, however, cannot trigger apoptosis." Apoptosis is therefore the fallback that removes a cell whose damage cannot be fixed; when p53 is non-functional, that fallback is lost, so the irreparably damaged cell survives and divides, passing its uncorrected mutations to its daughter cells. (Choice A) is wrong because the damaged version of p53 in cancer cells cannot trigger apoptosis at all, rather than triggering it prematurely. (Choice B) is correct because functional p53 induces apoptosis only when repair fails, and the faulty p53 cannot induce it, allowing the damaged cell to propagate. (Choice C) is wrong because Rb largely monitors cell size and binds the transcription factor E2F to block the G1/S transition; it is not the protein that triggers apoptosis. (Choice D) is wrong because apoptosis is the fallback invoked only when repair fails, not a routine step that always follows successful repair. This is a Scientific Reasoning and Problem Solving question because it requires chaining the apoptosis-as-safeguard mechanism with the consequence of p53 loss to predict why a damaged cell survives, rather than recalling a single isolated fact.$ex14$, 'hard', '2C', $cc14$Cell Cycle & Mitosis (BIO)$cc14$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a14A$Inverts the direction of the p53-apoptosis effect: claims faulty p53 over-triggers apoptosis when in fact it cannot trigger apoptosis at all.$a14A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a14C$Substitutes a real but wrong tumor-suppressor (Rb) as the apoptosis trigger; Rb actually monitors cell size and regulates E2F.$a14C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a14D$Treats apoptosis as a routine post-repair step rather than the fallback invoked only when repair fails.$a14D$ FROM q;

-- Q15 [Loss of Cell-Cycle Control & Cancer | hard | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub15$Loss of Cell-Cycle Control & Cancer$sub15$, $qt15$A researcher follows a population of normal epithelial cells and finds that whenever a cell breaks contact with the surrounding extracellular matrix, it dies within hours; she then examines a metastatic tumor line and finds that detached cells instead survive in circulation and seed colonies in distant tissues. Which explanation BEST accounts for both observations?$qt15$, $op15$[{"label": "A", "text": "Detached normal cells survive but stop dividing, and the metastatic cells differ only by reactivating division once they reach a new tissue."}, {"label": "B", "text": "Binding of extracellular-matrix receptors normally triggers apoptosis, so the metastatic cells escape death by shedding those receptors before they detach."}, {"label": "C", "text": "Detached normal cells lose the survival signaling that matrix-receptor binding provides and undergo apoptosis, whereas the metastatic cells survive detachment and proliferate at new sites."}, {"label": "D", "text": "Detached normal cells are eliminated because p21 destroys cells lacking matrix contact, and the metastatic cells carry a mutation that inactivates p21."}]$op15$::jsonb, 'C', $ex15$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is C because the survival of a normal animal cell depends on continuous signaling from receptors bound to the extracellular matrix, and losing that contact triggers apoptosis. The text states that "most normal animal cells have receptors that interact with the extracellular matrix" and that "the binding of cellular receptors to the extracellular matrix initiates a signaling cascade within the cell. However, if the cell moves away from the extracellular matrix, the signaling ceases, and the cell undergoes apoptosis." This system "keeps cells from traveling through the body and proliferating out of control, as happens with tumor cells that metastasize," so metastatic cells must survive detachment and proliferate at new sites rather than dying. (Choice A) is wrong because the normal fate of a detached cell is apoptosis, not a reversible halt in division; the cell dies rather than merely becoming quiescent. (Choice B) reverses the relationship: matrix-receptor binding sustains survival signaling, and it is the loss of that signaling, not its presence, that triggers apoptosis, so shedding receptors would not protect a cell. (Choice C) is correct because it captures both the loss of matrix-derived survival signaling that kills detached normal cells and the metastatic cells' ability to survive detachment and seed new sites. (Choice D) misassigns the mechanism: p21 "enforces the halt in the cycle dictated by p53 by binding to and inhibiting the activity of the Cdk/cyclin complexes" at the G1 checkpoint, so it is a cell-cycle brake, not the effector of anchorage-dependent apoptosis. This is a Scientific Reasoning and Problem Solving question because it requires interpreting two contrasting experimental observations and inferring the matrix-signaling mechanism that links normal anchorage-dependent apoptosis to its failure in metastasis.$ex15$, 'hard', '2C', $cc15$Cell Cycle & Mitosis (BIO)$cc15$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a15A$Treats detachment as causing reversible cell-cycle arrest (quiescence) rather than apoptosis, capturing the loss of division but missing that the cell actually dies.$a15A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a15B$Inverts the signaling logic so that ECM binding triggers apoptosis and detachment is protective, the opposite of survival signaling.$a15B$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a15D$Substitutes the real G1-checkpoint Cdk/cyclin inhibitor p21 as the apoptosis effector, borrowing a genuine cell-cycle regulator from the wrong process.$a15D$ FROM q;

-- Q16 [Mitosis Phases | easy | Skill 1 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub16$Mitosis Phases$sub16$, $qt16$A cytologist watching a dividing animal cell sees the protein that has been holding each pair of sister chromatids together suddenly degrade, after which the chromatids split apart at the centromere and each is dragged rapidly toward the pole its kinetochore microtubule connects to. The cell is in which phase of mitosis?$qt16$, $op16$[{"label": "A", "text": "Metaphase, when the chromosomes line up single-file along the metaphase plate while sister chromatids remain tightly attached"}, {"label": "B", "text": "Prophase, when the nuclear envelope dissociates into vesicles and the chromatin coils tightly to become visible under the light microscope"}, {"label": "C", "text": "Telophase, when nuclear envelopes re-form around the chromosomes and the chromosomes decondense back into stretched-out chromatin"}, {"label": "D", "text": "Anaphase, when the cohesin degrades, the sister chromatids separate at the centromere, and each is pulled toward an opposite pole"}]$op16$::jsonb, 'D', $ex16$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is D because the defining molecular event described—cohesin degrading so that the sister chromatids separate at the centromere and each is pulled toward the pole its microtubule is attached to—is the signature of anaphase. The text states, "The cohesin proteins degrade, and the sister chromatids separate at the centromere. Each chromatid, now called a single chromosome, is pulled rapidly toward the centrosome to which its microtubule is attached." Each of the three described features (cohesin loss, centromeric separation, poleward movement) is unique to anaphase among the mitotic phases, so the scenario points to anaphase and no other stage. (Choice A) Metaphase is when "All the chromosomes are aligned in a plane called the metaphase plate," but at that point "The sister chromatids are still tightly attached," so cohesin has not yet degraded. (Choice B) Prophase is when "the nuclear envelope starts to dissociate into small vesicles" and the chromatids "coil more tightly... and now become visible under a light microscope," which precedes any chromatid separation. (Choice C) Telophase is when "Nuclear envelopes form around the chromosomes" and the chromosomes "begin to decondense (unravel), relaxing once again into a stretched-out chromatin configuration," which occurs after the chromatids have already separated. (Choice D) is correct because cohesin degradation, centromeric separation of sisters, and poleward pulling toward the attached centrosome together define anaphase. This is a Knowledge of Scientific Concepts and Principles question because it requires recognizing the textbook-defined molecular and cellular hallmark of a specific mitotic phase.$ex16$, 'easy', '2C', $cc16$Cell Cycle & Mitosis (BIO)$cc16$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a16A$Confusing the adjacent prior phase (metaphase alignment with sisters still attached) for the separation event of anaphase$a16A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a16B$Citing a true but earlier-phase event (prophase nuclear envelope breakdown and chromatin condensation) instead of the anaphase event$a16B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a16C$Citing a true but later-phase event (telophase nuclear envelope re-formation and decondensation) instead of the anaphase event$a16C$ FROM q;

-- Q17 [Mitosis Phases | easy | Skill 1 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub17$Mitosis Phases$sub17$, $qt17$A cytologist watching a live animal cell under a light microscope sees the nuclear envelope begin fragmenting into small vesicles, the nucleolus fade from view, the duplicated sister chromatids coil tightly until they first appear as discrete bodies, and the two centrosomes start migrating toward opposite ends of the cell. These simultaneous changes mark the cell's entry into which phase of mitosis?$qt17$, $op17$[{"label": "A", "text": "Anaphase, when cohesin degrades and the sister chromatids separate at the centromere toward opposite poles"}, {"label": "B", "text": "Metaphase, when the fully formed chromosomes align along the plate midway between the two spindle poles"}, {"label": "C", "text": "Prophase, when the nuclear envelope dissociates, the nucleolus disperses, the chromatids condense, and the centrosomes move apart"}, {"label": "D", "text": "S phase, when DNA replicates so each chromosome becomes two sister chromatids joined at the centromere"}]$op17$::jsonb, 'C', $ex17$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is C because the cluster of events observed—nuclear envelope fragmenting into vesicles, the nucleolus disappearing, sister chromatids coiling until newly visible, and centrosomes migrating to opposite poles—is precisely the set that defines prophase, the first stage of mitosis. The text states that in prophase "the nuclear envelope starts to dissociate into small vesicles," "the nucleolus disappears (disperses) as well, and the centrosomes begin to move to opposite poles of the cell," and "the sister chromatids begin to coil more tightly... and now become visible under a light microscope." Each of these is a hallmark of prophase rather than any later mitotic stage or earlier interphase stage. (Choice A) Anaphase comes later: it is when "the cohesin proteins degrade, and the sister chromatids separate at the centromere," which has not yet happened here. (Choice B) Metaphase is when "all the chromosomes are aligned in a plane called the metaphase plate... roughly midway between the two poles," which follows the events described. (Choice C) is correct because every observed change matches the textbook's definition of prophase. (Choice D) S phase is part of interphase, where "DNA replication can proceed through the mechanisms that result in the formation of identical pairs of DNA molecules—sister chromatids," and "must always precede" mitosis rather than being one of its phases. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling and identifying the defining cellular events of a named mitotic phase directly from established biological description.$ex17$, 'easy', '2C', $cc17$Cell Cycle & Mitosis (BIO)$cc17$, 'biology', 1, 75
  ) RETURNING id
)
