UNION ALL SELECT id, 'C', 'process_step_confusion', $a18C$Attributing the arrest to an unrelated prophase event (nuclear-envelope dissociation) instead of the cohesin-dependent metaphase-to-anaphase transition$a18C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a18D$Conflating failure of sister-chromatid separation with failure of the actin contractile ring during cytokinesis, a real but distinct division defect$a18D$ FROM q;

-- Q19 [Mitosis Phases | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub19$Mitosis Phases$sub19$, $qt19$A geneticist images a cultured animal cell at metaphase and finds that every replicated chromosome is bioriented except one, whose single unattached kinetochore has not yet captured spindle microtubules from either pole; all spindle motors, cohesins, and separase are otherwise functional. The cell is monitored over the next several hours. What is the cell's most likely behavior?$qt19$, $op19$[{"label": "A", "text": "It arrests before mitosis because the G2 checkpoint detects the incompletely processed chromosome and bars entry into the mitotic phase."}, {"label": "B", "text": "It halts at metaphase and does not enter anaphase, because the M checkpoint blocks sister-chromatid separation until every kinetochore is properly anchored to the spindle."}, {"label": "C", "text": "It proceeds into anaphase on schedule and produces two daughter cells, one of which is left missing the chromosome that was unattached at the equator."}, {"label": "D", "text": "It proceeds into anaphase because the M checkpoint triggers a halt only when all kinetochores remain unattached, and a single lagging chromosome is tolerated."}]$op19$::jsonb, 'B', $ex19$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is B because the M checkpoint, also called the spindle checkpoint, monitors kinetochore-spindle attachment at metaphase and will not allow the cycle to advance into anaphase until every kinetochore is anchored. The text states that the M checkpoint \"determines whether all the sister chromatids are correctly attached to the spindle microtubules,\" and that \"[b]ecause the separation of the sister chromatids during anaphase is an irreversible step, the cycle will not proceed until the kinetochores of each pair of sister chromatids are firmly anchored to at least two spindle fibers arising from opposite poles of the cell.\" Because anaphase cannot be undone, a single unattached kinetochore is sufficient to keep the cell halted in metaphase rather than risk an unequal partition. (Choice A) is wrong because the G2 checkpoint acts before the mitotic phase to verify chromosome replication and DNA integrity, not kinetochore attachment, which is assessed only once the cell is already in metaphase. (Choice B) is correct because the unsatisfied spindle checkpoint blocks the irreversible anaphase transition until the last kinetochore is anchored. (Choice C) is wrong because allowing anaphase to proceed on schedule is exactly the missegregation outcome the M checkpoint exists to prevent; the checkpoint holds the cell rather than letting it divide unequally. (Choice D) is wrong because the checkpoint requires that every kinetochore be attached, so even one unanchored kinetochore is enough to maintain the halt rather than being tolerated. This is a Scientific Reasoning and Problem Solving question because it requires predicting a cell's behavior by combining the surveillance role of the spindle checkpoint with the irreversibility of anaphase to determine that division is withheld.$ex19$, 'hard', '2C', $cc19$Cell Cycle & Mitosis (BIO)$cc19$, 'biology', 2, 110
  ) RETURNING id
)
