SELECT id, 'B', 'adjacent_fact', $a21B$Naming a real centrosome/pole component (centriole) as the chromatid-level microtubule attachment site$a21B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a21C$Confusing the structure that holds sister chromatids together (cohesin) with the structure that binds spindle microtubules$a21C$ FROM q
