-- Q23 [Mitotic Structures | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub23$Mitotic Structures$sub23$, $qt23$A researcher imaging a dividing animal cell records the exact moment cohesin proteins are cleaved at the centromere, freeing the two sister chromatids of a chromosome from each other. The researcher then tracks one chromatid as it begins to travel poleward. Which event most directly accounts for the movement of that chromatid toward its pole?$qt23$, $op23$[{"label": "A", "text": "The cohesin proteins at the centromere actively contract and reel the chromatid toward the centrosome to which it is attached."}, {"label": "B", "text": "Polar microtubules from the opposite pole shorten and drag the chromatid inward toward the metaphase plate."}, {"label": "C", "text": "The kinetochore microtubule shortens and pulls the chromatid toward the centrosome to which that microtubule is attached."}, {"label": "D", "text": "Astral microtubules near the pole lengthen and push the chromatid away from the equator toward the nearer pole."}]$op23$::jsonb, 'C', $ex23$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is C because, once cohesin is degraded, the spindle microtubule bound to the chromatid's kinetochore is what shortens and pulls the now-separated chromatid toward the centrosome it is attached to. The text states that in anaphase "The cohesin proteins degrade, and the sister chromatids separate at the centromere. Each chromatid, now called a single chromosome, is pulled rapidly toward the centrosome to which its microtubule is attached." The microtubules that engage the chromosome do so by binding the kinetochore in its centromeric region, so the kinetochore microtubule is the structure responsible for the poleward pull. The polar and astral microtubules described elsewhere serve other roles and do not move the chromatids poleward. (Choice A) Cohesin does not contract or generate force; the text says cohesin proteins simply "degrade," releasing the chromatids rather than reeling them in. (Choice B) Polar microtubules "do not engage the chromosomes" and instead "slide against each other at the metaphase plate," driving cell elongation, not chromatid movement, and they would draw a chromatid toward the equator rather than its pole. (Choice C) The kinetochore microtubule attached to the chromatid shortens and pulls it toward its centrosome, matching the text's account of anaphase movement. (Choice D) Astral microtubules "are located near the poles, aid in spindle orientation, and are required for the regulation of mitosis," so they orient the spindle rather than pushing chromatids away from the equator. This is a Scientific Reasoning and Problem Solving question because the student must connect the structural role of kinetochore-bound spindle microtubules to the predicted direction and cause of chromatid movement, while ruling out other microtubule populations and the non-motor role of cohesin.$ex23$, 'medium', '2C', $cc23$Cell Cycle & Mitosis (BIO)$cc23$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a23A$Casting cohesin (which passively degrades to release chromatids) as an active force-generating structure that reels chromatids poleward$a23A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a23B$Confusing polar microtubules (which slide at the metaphase plate for elongation and do not engage chromosomes) with the chromatid-pulling kinetochore microtubules$a23B$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a23D$Citing astral microtubules' real function (spindle orientation/regulation near poles) but wrongly assigning them a pushing role in chromatid movement$a23D$ FROM q;

-- Q24 [Mitotic Structures | hard | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub24$Mitotic Structures$sub24$, $qt24$A researcher arrests a cultured animal cell so that DNA replication completes normally but centrosome duplication is blocked, leaving the cell with a single microtubule-organizing center as it enters mitosis. What outcome does this single-MTOC condition most directly produce as the cell attempts division?$qt24$, $op24$[{"label": "A", "text": "The lone centrosome organizes a normal bipolar spindle, because each kinetochore independently captures microtubules and defines its own pole"}, {"label": "B", "text": "The sister chromatids fail to condense and no kinetochores form, because kinetochore assembly is triggered by the second centrosome"}, {"label": "C", "text": "DNA replication is blocked at the G1 checkpoint, because that checkpoint counts centrosomes before allowing entry into S phase"}, {"label": "D", "text": "A bipolar spindle fails to form, so the duplicated chromosomes are not partitioned into two normal daughter nuclei"}]$op24$::jsonb, 'D', $ex24$This is a Biology question that falls under the content category 'Cell Cycle & Mitosis (BIO)'. The answer is D because a bipolar spindle requires two separate microtubule-organizing centers that migrate to opposite poles, and with only one MTOC present that two-pole geometry cannot be established. The text states that the centrosome "is also duplicated during the S phase" and that "the two centrosomes will give rise to the mitotic spindle, the apparatus that orchestrates the movement of chromosomes during mitosis," while during prophase "the centrosomes begin to move to opposite poles of the cell" and "microtubules that will form the mitotic spindle extend between the centrosomes." Because microtubules grow from MTOCs located at opposite poles and pull each sister chromatid toward the pole it faces, a single MTOC cannot generate two opposing poles, so the duplicated chromosomes cannot be drawn apart into two equal sets and normal partitioning into two daughter nuclei fails. (Choice A) is wrong because kinetochores do not define their own poles; the text describes microtubules extending from the centrosomes to bind kinetochores, so spindle polarity comes from the MTOCs, not the kinetochores. (Choice B) is wrong because chromosome condensation (via condensin) and kinetochore assembly at the centromeric region occur in prophase and prometaphase and are not triggered by a second centrosome. (Choice C) is wrong because the G1 checkpoint assesses DNA damage, cell size, and reserves rather than centrosome number, and in this scenario replication has already completed normally. (Choice D) is correct because one MTOC cannot build the two opposing poles a bipolar spindle requires, so the chromosomes are not segregated into two normal daughter nuclei. This is a Scientific Reasoning and Problem Solving question because it requires predicting a downstream segregation failure from an experimentally imposed structural lesion rather than recalling a stated fact.$ex24$, 'hard', '2C', $cc24$Cell Cycle & Mitosis (BIO)$cc24$, 'biology', 2, 150
  ) RETURNING id
)
